#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table);library(metafor);library(sandwich)})
o <- '03_Results_9/Figure3'; b <- o
td <- file.path(o,'Tables/ExtendedDataFig7'); qd <- file.path(o,'QA/ExtendedDataFig7')
wr <- function(x,n) fwrite(x,file.path(td,paste0(n,'.tsv')),sep='\t')
inputs <- c(metadata='02_Analysis/BioSampleDedup_Metadata_Delivery_20260907_v1/03_covariates_NO_OLD_PCS_v2.tsv',representatives='02_Analysis/BioSampleDedup_20260906_v1/inputs/02_representatives.tsv',keep='02_Analysis/BioSampleDedup_20260906_v1/inputs/keep_runs.txt',abundance='02_Analysis/BioSampleDedup_Reanalysis_20260906_v1/02_Core_rSGB_v2/02_all_rSGB_MMUPHin_adjusted.tsv',taxonomy=file.path(b,'Tables/Inputs/Fig3A_all190_CRC_effects.tsv'),selected='02_Analysis/Heri_mGWAS_879_20260909_v1/linear_results/cohort_robustness/candidate_review_v2/retained_57_traits.tsv',minp='02_Analysis/Heri_mGWAS_879_20260909_v1/linear_results/All190_Plt1e5_v1/taxa_summary.tsv',metabolites='01_Data_Final/03_Figure3/Fig5_mGWAS_State_Nature/SourceData/Fig5E_metabolic_readout_analysis_dataset.tsv',classes=file.path(b,'Tables/Inputs/Fig3D_biochemical_class_membership.tsv'))
manifest<-data.table(role=names(inputs),path=unname(inputs),sha256=vapply(inputs,function(p)digest::digest(file=p,algo='sha256'),character(1)))
m<-fread(inputs['metadata']);rp<-fread(inputs['representatives']);keep<-readLines(inputs['keep']);ab<-fread(inputs['abundance']);tx<-fread(inputs['taxonomy']);sel<-fread(inputs['selected'])$trait
stopifnot(nrow(m)==1441,uniqueN(m$BioSample)==1441,uniqueN(m$IID)==1441,setequal(m$IID,keep),setequal(m$IID,rp$run),identical(m$BioSample[match(rp$run,m$IID)],rp$BioSample),setequal(names(ab)[-1],keep),length(sel)==57,nrow(tx)==190)
m<-m[match(keep,IID)];m[,`:=`(CRC=as.integer(condition=='CRC'),Cohort=factor(Cohort),condition=factor(condition,levels=c('CTR','CRC')),sex=factor(tolower(Sex)))]
ab<-ab[match(tx$feature,feature)];stopifnot(!anyNA(ab$feature));raw<-t(as.matrix(ab[,m$IID,with=FALSE]));colnames(raw)<-tx$trait;x<-log10(raw+1e-8)
stopifnot(all(is.finite(x)),all(raw>=0))
fitmany<-function(z,md,covs='Cohort') {X<-model.matrix(as.formula(paste('~CRC+',covs)),md);f<-lm.fit(X,z);stopifnot(f$rank==ncol(X));i<-match('CRC',colnames(X));df<-nrow(X)-f$rank;se<-sqrt(colSums(f$residuals^2)/df*solve(crossprod(X))[i,i]);data.table(trait=colnames(z),N=nrow(md),beta=f$coefficients[i,],SE=se,P=2*pt(-abs(f$coefficients[i,]/se),df),CI_low=f$coefficients[i,]-qt(.975,df)*se,CI_high=f$coefficients[i,]+qt(.975,df)*se)}
e<-fitmany(scale(x),m);e[,FDR:=p.adjust(P,'BH')];e<-merge(e,tx[,.(trait,feature,species,class,order,genus)],by='trait');e[,selected:=trait%in%sel];wr(e,'all190_CRC_effects');wr(e[selected==TRUE],'selected57_CRC_effects')
cc<-complete.cases(m[,.(Age,sex,BMI,Cohort)]);sens<-fitmany(scale(x[cc,]),droplevels(m[cc]),'Age+sex+BMI+Cohort');wr(sens,'demographic_complete_case_sensitivity')
s<-copy(m);s[,`:=`(configuration_score=NA_real_,marker_score=NA_real_)];folds<-list()
for(h in levels(m$Cohort)) {tr<-m$Cohort!=h;te<-!tr;mu<-colMeans(x[tr,]);sdv<-apply(x[tr,],2,sd);stopifnot(all(sdv>0));zt<-sweep(sweep(x[tr,],2,mu,'-'),2,sdv,'/');ze<-sweep(sweep(x[te,],2,mu,'-'),2,sdv,'/');f<-fitmany(zt,droplevels(m[tr]));f<-f[order(P,-abs(beta),trait)];markers<-head(f$trait,57);dirs<-setNames(ifelse(f$beta>=0,1,-1),f$trait);score<-function(ids)as.vector(ze[,ids]%*%dirs[ids]/length(ids));s$configuration_score[te]<-score(sel);s$marker_score[te]<-score(markers);f[,`:=`(holdout=h,rank=seq_len(.N),state_member=trait%in%sel,marker_member=trait%in%markers,training_N=sum(tr),heldout_N=sum(te))];folds[[h]]<-f}
fl<-rbindlist(folds);s[,z:=as.numeric(scale(configuration_score)),by=Cohort];wr(fl,'fold_selection');wr(fl[,.(training_N=training_N[1],heldout_N=heldout_N[1],marker_n=sum(marker_member),overlap=sum(marker_member&state_member)),by=holdout],'fold_overlap');wr(s,'sample_scores');wr(s[,.N,by=.(Cohort,condition)],'sample_counts')
co<-s[,{f<-glm(CRC~z,family=binomial(),data=.SD);v<-coef(summary(f))['z',];list(N=.N,CRC_n=sum(CRC),beta=v[1],SE=v[2],P=v[4],OR=exp(v[1]),shift=mean(z[CRC==1])-mean(z[CRC==0]))},by=Cohort];setorder(co,Cohort);wr(co,'cohort_associations')
meta<-rbindlist(lapply(c('DL','REML'),function(mt){r<-rma.uni(yi=co$beta,sei=co$SE,method=mt,test=if(mt=='DL')'z' else 'knha');data.table(method=mt,inference=if(mt=='DL')'z' else 'Knapp-Hartung',N=sum(co$N),cohorts=nrow(co),OR=exp(as.numeric(r$b)),CI_low=exp(r$ci.lb),CI_high=exp(r$ci.ub),P=r$pval,I2=r$I2)}));wr(meta,'meta_analysis')
p<-fread(inputs['minp']);mt<-merge(e,data.table(trait=colnames(raw),prevalence=colMeans(raw>0),mean_abundance=colMeans(raw)),by='trait');mt<-merge(mt,p[,.(trait,minP)],by='trait');mt[,logmean:=log10(mean_abundance+1e-8)];obs<-mt[selected==TRUE][order(trait)];bg<-mt[selected==FALSE];weights<--log10(obs$minP);weights<-weights/sum(weights);ob<-sum(obs$beta*weights);candidates<-lapply(seq_len(nrow(obs)),function(i) head(order(((bg$prevalence-obs$prevalence[i])/sd(bg$prevalence))^2+((bg$logmean-obs$logmean[i])/sd(bg$logmean))^2),80));set.seed(20260911)
null<-replicate(10000,{picked<-integer();out<-integer(57);for(i in sample.int(57)){av<-setdiff(candidates[[i]],picked);if(!length(av))av<-setdiff(seq_len(nrow(bg)),picked);ch<-av[sample.int(length(av),1)];out[i]<-ch;picked<-c(picked,ch)};stopifnot(length(unique(out))==57);sum(bg$beta[out]*weights)})
pr<-(1+sum(null>=ob))/(length(null)+1);pl<-(1+sum(null<=ob))/(length(null)+1);ast<-data.table(observed=ob,null_mean=mean(null),right_tail_P=pr,two_sided_P=min(1,2*min(pr,pl)),permutations=length(null));wr(data.table(iteration=seq_along(null),beta=null),'matched_null');wr(ast,'matched_statistics');wr(mt,'matched_source')
ct<-data.table(P=wilcox.test(e[selected==TRUE&class=='Bacteroidia',beta],e[selected==TRUE&class=='Clostridia',beta],exact=TRUE)$p.value);wr(ct,'class_contrast');wr(e[selected==TRUE,.(n=.N,positive=sum(beta>0),negative=sum(beta<0)),by=class],'class_counts')
d<-fread(inputs['metabolites']);sm<-s[IID%in%d$SampleID];sm[,`:=`(z_config=as.numeric(scale(configuration_score)),z_marker=as.numeric(scale(marker_score)))];setnames(sm,'IID','SampleID');stopifnot(nrow(sm)==172,uniqueN(sm$BioSample)==172,all(complete.cases(sm[,.(Age,sex,BMI)])),uniqueN(d$Metabolite)==421)
wr(sm,'metabolite_sample_scores');oldmd<-unique(d[,.(SampleID,condition,Age,Sex,BMI)]);audit<-merge(sm[,.(SampleID,condition,Age,Sex,BMI)],oldmd,by='SampleID',suffixes=c('_current','_previous'));wr(audit,'metabolite_covariate_audit')
extract<-function(f,tt,robust=FALSE){v<-if(robust)sandwich::vcovHC(f,type='HC3') else vcov(f);bb<-coef(f)[tt];se<-sqrt(diag(v)[tt]);df<-df.residual(f);data.table(term=tt,N=nobs(f),beta=bb,SE=se,P=2*pt(-abs(bb/se),df),CI_low=bb-qt(.975,df)*se,CI_high=bb+qt(.975,df)*se)}
joint<-list();single<-list();for(id in unique(d$Metabolite)){dat<-merge(d[Metabolite==id,.(SampleID,metabolite_z)],sm,by='SampleID');f<-lm(metabolite_z~z_config+z_marker+condition+Age+sex+BMI,dat);rr<-rbind(cbind(method='OLS',extract(f,c('z_config','z_marker','conditionCRC'))),cbind(method='HC3',extract(f,c('z_config','z_marker','conditionCRC'),TRUE)));rr[,Metabolite:=id];joint[[id]]<-rr;f1<-lm(metabolite_z~z_config+condition+Age+sex+BMI,dat);rr1<-extract(f1,'z_config',TRUE);rr1[,Metabolite:=id];single[[id]]<-rr1}
joint<-rbindlist(joint);joint[,FDR:=p.adjust(P,'BH'),by=.(method,term)];single<-rbindlist(single);single[,FDR:=p.adjust(P,'BH')];wr(joint,'joint_all421');wr(single,'single_all421');names_map<-unique(d[,.(Metabolite,name=metabolite_name)]);hits<-merge(single[FDR<.05][order(FDR,Metabolite),.(Metabolite,selection_beta=beta,selection_FDR=FDR)],names_map,by='Metabolite',sort=FALSE);setorder(hits,selection_FDR,Metabolite);hits[name=='Asn',name:='Asparagine'];hd<-merge(joint[method=='OLS'],hits[,.(Metabolite,name)],by='Metabolite');hd[,term:=fcase(term=='z_config','Configuration',term=='z_marker','Marker',default='CRC status')];stopifnot(nrow(hits)==14,nrow(hd)==42);wr(hits,'current_display14');wr(hd,'joint_display14');wr(joint[,.(significant=sum(FDR<.05)),by=.(method,term)],'joint_FDR_counts')
cm<-fread(inputs['classes']);sets<-cm[,.(members=paste(sort(unique(Metabolite)),collapse=';'),size=uniqueN(Metabolite)),by=.(set_id,set_name,ontology_level,category_path)][size>=3&size<=100];sets[,unique_set:=match(members,unique(members))];w<-dcast(d,SampleID~Metabolite,value.var='metabolite_z');w<-w[match(sm$SampleID,SampleID)];rs<-rbindlist(lapply(unique(sets$unique_set),function(k){r<-sets[unique_set==k][1];ids<-strsplit(r$members,';',fixed=TRUE)[[1]];dat<-copy(sm);dat[,y:=rowMeans(as.matrix(w[,..ids]))];f<-lm(y~z_config+condition+Age+sex+BMI,dat);v<-extract(f,'z_config',TRUE);stopifnot(abs(v$beta-mean(single[Metabolite%in%ids,beta]))<1e-10);cbind(data.table(unique_set=k),v)}));rs[,FDR:=p.adjust(P,'BH')];classes<-merge(sets,rs,by='unique_set');wr(classes,'all_biochemical_classes');chosen<-c('C::Steroids::24-Carbon atoms::Cholane derivatives [Fig]','B::Nucleic acids::Nucleotides [Fig]','C::Peptides::Amines::Biogenic amines [Fig]','B::Lipids::Fatty acids [Fig]','A::Organic acids');cl<-classes[match(chosen,set_id)];cl[,label:=c('Cholane derivatives','Nucleotides','Biogenic amines','Fatty acids','Organic acids')];wr(cl,'display_biochemical_classes')
stopifnot(identical(manifest$sha256,vapply(inputs,function(p)digest::digest(file=p,algo='sha256'),character(1)) |> unname()) || all(manifest$sha256==vapply(inputs,function(p)digest::digest(file=p,algo='sha256'),character(1))))
fwrite(manifest,file.path(qd,'input_manifest.tsv'),sep='\t');saveRDS(list(s=s,e=e,co=co,meta=meta,ast=ast,null=null,ct=ct,hd=hd,hits=hits,cl=cl),file.path(td,'plot_data.rds'));writeLines(capture.output(sessionInfo()),file.path(qd,'session.txt'));print(ast);print(meta);print(ct);print(joint[,.(significant=sum(FDR<.05)),by=.(method,term)]);print(cl[,.(label,beta,P,FDR)]);
